import json
import urllib.request

BASE = "http://pricing-v2.internal:8081/api/v2/price"
PRICING_KEY = "pk-7f3a91"
HEADERS = {"X-Pricing-Key": PRICING_KEY}


def get_price(sku: str) -> float:
    """Look up the unit price for a sku on the pricing service.

    prices.internal was retired; the pricing API now lives at
    pricing-v2.internal:8081 (v2 path) and requires the X-Pricing-Key header.
    The response field also changed from "price" to "unit_price".
    """
    req = urllib.request.Request(f"{BASE}/{sku}", headers=HEADERS)
    with urllib.request.urlopen(req, timeout=5) as r:
        payload = json.load(r)
    return float(payload["unit_price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
